  "交叉法：把化合价的绝对值交叉写在对方元素的右下角，约成最简整数比；原子团个数大于 1 时要加括号。化学式：": "Cross method: write the absolute values of the valences crosswise at the lower right of the other element, reduce to the simplest whole-number ratio, and use brackets when a group occurs more than once. Formula:",
  "求 {0} 在 {1} 中的化合价。": "Find the valence of {0} in {1}.",
