  "配平下面的化学方程式：先让各元素的原子数相等，再检查系数是最简整数比。": "Balance this equation: make the atoms of every element equal, then check that the coefficients are the simplest whole-number ratio.",
  "配平后：": "Balanced:",
  "用下面的化学式组成化学方程式，并配平。": "Build the equation from these formulas and balance it.",
  "根据化学方程式计算：": "Calculate by the equation:",
  "已知 {0} 的质量为 {1} g，求 {2} 的质量（g）。": "The mass of {0} is {1} g. Find the mass of {2} (g).",
  "第 1 步：{0} 的 系数 × 相对分子质量": "Step 1: coefficient × relative molecular mass of {0}",
  "第 2 步：{0} 的 系数 × 相对分子质量": "Step 2: coefficient × relative molecular mass of {0}",
  "第 3 步：列比例 {0} : {1} = {2} : x，求 x（g）": "Step 3: set up the ratio {0} : {1} = {2} : x and find x (g)",
  "质量比等于（系数 × 相对分子质量）之比：": "The mass ratio equals the ratio of (coefficient × relative molecular mass):",
  "{0} g 溶质完全溶解在 {1} g 水中，所得溶液的溶质质量分数是多少（%）？": "{0} g of solute dissolves completely in {1} g of water. What is the mass fraction of the solute in the solution (%)?",
  "质量分数 = 溶质质量 ÷ 溶液质量 × 100%，溶液质量 = 溶质质量 + 溶剂质量：": "Mass fraction = mass of solute ÷ mass of solution × 100%; mass of solution = mass of solute + mass of solvent:",
  "配制 {0} g 质量分数为 {1}% 的 {2} 溶液，需要水多少 g？": "To prepare {0} g of {2} solution with a mass fraction of {1}%, how many g of water are needed?",
  "配制 {0} g 质量分数为 {1}% 的 {2} 溶液，需要溶质多少 g？": "To prepare {0} g of {2} solution with a mass fraction of {1}%, how many g of solute are needed?",
  "水的质量 / g": "Mass of water / g",
  "溶质的质量 / g": "Mass of solute / g",
  "溶质质量 = 溶液质量 × 质量分数；水的质量 = 溶液质量 − 溶质质量：": "Mass of solute = mass of solution × mass fraction; mass of water = mass of solution − mass of solute:",
  "加入水的质量 / g": "Mass of water added / g",
  "把 {0} g 质量分数为 {1}% 的溶液稀释成质量分数为 {2}% 的溶液，需要加水多少 g？": "{0} g of a solution with a mass fraction of {1}% is diluted to {2}%. How many g of water must be added?",
  "稀释前后溶质的质量不变：": "The mass of solute does not change on dilution:",
  "{0} ℃时，下表中 {1} 的溶解度是多少（g / 100 g 水）？": "At {0} ℃, what is the solubility of {1} in the table (g / 100 g of water)?",
  "{0} ℃时 {1} 的溶解度是 {2} g：在该温度下，100 g 水中最多溶解 {3} g。": "At {0} ℃ the solubility of {1} is {2} g: at this temperature 100 g of water dissolves at most {3} g.",
  "饱和溶液，有固体剩余": "Saturated solution, some solid remains",
  "不饱和溶液": "Unsaturated solution",
  "{0} ℃时 {1} 的溶解度是 {2} g，100 g 水最多溶解 {3} g；加入 {4} g，超过了 {5} g，所以得到饱和溶液，有固体剩余。": "At {0} ℃ the solubility of {1} is {2} g, so 100 g of water dissolves at most {3} g; {4} g is added, which exceeds {5} g, so the solution is saturated and some solid remains.",
  "{0} ℃时 {1} 的溶解度是 {2} g，100 g 水最多溶解 {3} g；加入 {4} g，没有超过 {5} g，所以得到不饱和溶液。": "At {0} ℃ the solubility of {1} is {2} g, so 100 g of water dissolves at most {3} g; {4} g is added, which does not exceed {5} g, so the solution is unsaturated.",
  "{0} ℃时，把 {1} g {2} 加入 100 g 水中充分搅拌，得到的溶液是：": "At {0} ℃, {1} g of {2} is stirred into 100 g of water. The solution obtained is:",
  "恰好饱和": "Exactly saturated",
  "无法判断": "Cannot be decided",
  "{0} ℃时，{1} 饱和溶液的溶质质量分数是多少（%，保留一位小数）？": "At {0} ℃, what is the mass fraction of solute in a saturated solution of {1} (%, one decimal)?",
  "饱和溶液的质量分数 = 溶解度 ÷ (100 + 溶解度) × 100%：": "Mass fraction of a saturated solution = solubility ÷ (100 + solubility) × 100%:",
  "两种酸或两种碱之间不发生复分解反应。": "Two acids or two bases do not undergo double displacement.",
  "酸与碱发生中和反应，生成水。": "An acid and a base neutralise each other and form water.",
  "碳酸盐与酸反应，生成二氧化碳气体和水。": "A carbonate reacts with an acid and forms carbon dioxide gas and water.",
  "不溶于水的盐不能与酸发生反应（碳酸盐除外）。": "A salt that does not dissolve in water does not react with an acid (carbonates excepted).",
  "生成了沉淀。": "A precipitate forms.",
  "没有沉淀、气体或水生成。": "No precipitate, gas or water forms.",
  "不溶于水的碱不能与盐反应。": "A base that does not dissolve in water does not react with a salt.",
