  "把下面的物质拖到所属的类别中（也可以先点物质，再点类别）。": "Drag each substance into its class (or tap the substance first, then the class).",
  "纯净物分为单质和化合物；由两种元素组成、其中一种是氧的化合物是氧化物；酸、碱、盐是三类不同的化合物；混合物由多种物质组成。": "Pure substances are elements or compounds; an oxide is a compound of two elements, one of which is oxygen; acids, bases and salts are three kinds of compounds; a mixture consists of several substances.",
  "酸性": "acidic",
  "中性": "neutral",
  "碱性": "alkaline",
  "无色": "Colourless",
  "遇到{0}溶液显示的颜色是：": "Its colour in a {0} solution is:",
  "：酸性 {0}，中性 {1}，碱性 {2}。": ": acidic {0}, neutral {1}, alkaline {2}.",
  "的 pH 约为 {0}，它是：": "has a pH of about {0}. It is:",
  "pH < 7 显酸性，pH = 7 显中性，pH > 7 显碱性。pH 约为 {0}，所以显{1}。": "pH < 7 is acidic, pH = 7 is neutral, pH > 7 is alkaline. The pH is about {0}, so it is {1}.",
  "下列溶液中，酸性最强的是：": "Which of these solutions is the most acidic?",
  "下列溶液中，碱性最强的是：": "Which of these solutions is the most alkaline?",
  "pH 越小，酸性越强。": "The lower the pH, the stronger the acidity.",
  "pH 越大，碱性越强。": "The higher the pH, the stronger the alkalinity.",
  "下列溶液中，能使无色酚酞溶液变红的是：": "Which of these solutions turns colourless phenolphthalein red?",
  "无色酚酞溶液遇碱性溶液变红，遇酸性或中性溶液不变色。": "Colourless phenolphthalein turns red in an alkaline solution and stays colourless in an acidic or neutral one.",
  "向稀盐酸中不断滴加氢氧化钠溶液，溶液的 pH 变化是：": "Sodium hydroxide solution is added continuously to dilute hydrochloric acid. The pH:",
  "逐渐增大": "Increases gradually",
  "酸被中和，酸性减弱，pH 增大；恰好中和时 pH = 7，氢氧化钠过量后 pH 大于 7。": "The acid is neutralised, the acidity decreases and the pH rises; at exact neutralisation pH = 7, and with excess sodium hydroxide the pH is above 7.",
  "逐渐减小": "Decreases gradually",
  "不变": "Does not change",
  "先增大后减小": "Rises, then falls",
  "向氢氧化钠溶液中不断滴加稀盐酸，溶液的 pH 变化是：": "Dilute hydrochloric acid is added continuously to sodium hydroxide solution. The pH:",
  "碱被中和，碱性减弱，pH 减小；恰好中和时 pH = 7，盐酸过量后 pH 小于 7。": "The base is neutralised, the alkalinity decreases and the pH falls; at exact neutralisation pH = 7, and with excess hydrochloric acid the pH is below 7.",
  "先减小后增大": "Falls, then rises",
  "向稀盐酸中加水稀释，溶液的 pH 变化是：": "Water is added to dilute hydrochloric acid. The pH:",
  "逐渐增大，但始终小于 7": "Increases gradually but always stays below 7",
  "酸性减弱，pH 增大，但稀释不能使酸变成碱，pH 只会无限接近 7。": "The acidity decreases and the pH rises, but dilution cannot turn an acid into a base: the pH only comes ever closer to 7.",
  "逐渐增大，最后大于 7": "Increases gradually and ends above 7",
  "向氢氧化钠溶液中加水稀释，溶液的 pH 变化是：": "Water is added to sodium hydroxide solution. The pH:",
  "逐渐减小，但始终大于 7": "Decreases gradually but always stays above 7",
  "碱性减弱，pH 减小，但稀释不能使碱变成酸，pH 只会无限接近 7。": "The alkalinity decreases and the pH falls, but dilution cannot turn a base into an acid: the pH only comes ever closer to 7.",
  "逐渐减小，最后小于 7": "Decreases gradually and ends below 7",
  "酸雨是指 pH 小于多少的雨水：": "Acid rain is rain with a pH below:",
  "正常雨水溶有二氧化碳，pH 约为 5.6；pH 小于 5.6 的雨水叫酸雨。": "Normal rain contains dissolved carbon dioxide and has a pH of about 5.6; rain with a pH below 5.6 is acid rain.",
