  "分解反应": "Réaction de décomposition",
  "置换反应": "Réaction de substitution",
  "其他反应": "Autre réaction",
  "化合反应：两种或两种以上的物质生成一种物质（多变一）。": "Réaction de synthèse : deux substances ou plus forment une seule substance.",
  "分解反应：一种物质生成两种或两种以上的物质（一变多）。": "Réaction de décomposition : une substance forme deux substances ou plus.",
  "置换反应：一种单质与一种化合物反应，生成另一种单质和另一种化合物。": "Réaction de substitution : un corps simple réagit avec un composé et forme un autre corps simple et un autre composé.",
  "复分解反应：两种化合物互相交换成分，生成另外两种化合物。": "Réaction de double substitution : deux composés échangent leurs constituants et forment deux autres composés.",
  "不属于四种基本反应类型，例如氧气与有机物的反应，或非金属氧化物与碱、一氧化碳与金属氧化物的反应。": "Ne relève pas des quatre types de base, par exemple le dioxygène avec un composé organique, un oxyde non métallique avec une base, ou le monoxyde de carbone avec un oxyde métallique.",
  "已知化合价：{0} 为 {1}，{2} 为 {3}。写出它们组成的化合物的化学式。": "Valences données : {0} vaut {1}, {2} vaut {3}. Écrivez la formule du composé qu'ils forment.",
  "交叉法：把化合价的绝对值交叉写在对方元素的右下角，约成最简整数比；原子团个数大于 1 时要加括号。化学式：": "Méthode croisée : écrivez les valeurs absolues des valences en croix, en indice de l'autre élément, simplifiez au plus petit rapport entier et mettez des parenthèses quand un groupe figure plus d'une fois. Formule :",
  "求 {0} 在 {1} 中的化合价。": "Trouvez la valence de {0} dans {1}.",
  "在化合物中各元素化合价的代数和为零。设该元素的化合价为 x：": "Dans un composé, la somme des valences est nulle. Soit x la valence de l'élément :",
  "得 x = {0}。": "Donc x = {0}.",
