  "计算相对分子质量：{0}": "Calculez la masse moléculaire relative : {0}",
  "相对分子质量": "Masse moléculaire relative",
  "相对分子质量等于各原子的相对原子质量之和：": "La masse moléculaire relative est la somme des masses atomiques relatives de tous les atomes :",
