  "质量分数 / %": "Fraction massique / %",
  "元素的质量分数 = 该元素的相对原子质量之和 ÷ 相对分子质量 × 100%：": "Fraction massique d'un élément = somme de ses masses atomiques relatives ÷ masse moléculaire relative × 100 % :",
