  "金属活动性顺序（由强到弱）：": "Série d'activité des métaux (du plus au moins actif) :",
  "下列金属中，不能与稀盐酸反应放出氢气的是：": "Lequel de ces métaux ne réagit pas avec l'acide chlorhydrique dilué pour donner du dihydrogène ?",
  "下列金属中，不能与稀硫酸反应放出氢气的是：": "Lequel de ces métaux ne réagit pas avec l'acide sulfurique dilué pour donner du dihydrogène ?",
  "{0} 排在氢的后面，不能置换出酸中的氢。": "{0} est après l'hydrogène et ne peut pas déplacer l'hydrogène d'un acide.",
  "金属活动性顺序：": "Série d'activité des métaux :",
  "{0} 排在氢的前面，能置换出酸中的氢：": "{0} est avant l'hydrogène et déplace l'hydrogène d'un acide :",
  "铁与稀酸反应生成亚铁盐（+2 价）。": "Le fer et un acide dilué forment un sel de fer(II) (valence +2).",
  "{0} 排在氢的后面，不能与稀酸反应。": "{0} est après l'hydrogène et ne réagit pas avec un acide dilué.",
  "{0} 与稀盐酸混合：": "{0} est mélangé à de l'acide chlorhydrique dilué :",
  "{0} 与稀硫酸混合：": "{0} est mélangé à de l'acide sulfurique dilué :",
  "{0} 比 {1} 活泼，能把 {2} 从盐溶液中置换出来：": "{0} est plus actif que {1} et déplace {2} de sa solution saline :",
  "{0} 不如 {1} 活泼，不能把 {2} 从盐溶液中置换出来，不反应。": "{0} est moins actif que {1} et ne peut pas déplacer {2} de sa solution saline : pas de réaction.",
  "{0} 放入 {1} 溶液中：": "{0} est plongé dans une solution de {1} :",
  "单质": "Corps simples",
  "氧化物": "Oxydes",
  "酸类": "Acides",
  "碱类": "Bases",
