  "天文": "Astronomie",
  "太阳系 · 月相 · 星空": "Système solaire · Phases de la Lune · Étoiles",
  "太阳系": "Système solaire",
  "实验室": "Laboratoire",
  "星空": "Ciel étoilé",
  "你知道吗？": "Le saviez-vous ?",
  "换一条": "Un autre",
  "矮行星": "Planète naine",
  "行星": "Planète",
  "行星和矮行星": "Planètes et planètes naines",
  "每次 10 题：认行星、认卫星、认星座、认月相，还有地球和宇宙的知识。没有时间限制，每题答完后有解释。": "10 questions à chaque fois : planètes, lunes, constellations, phases de la Lune, et connaissances sur la Terre et l'univers. Il n'y a pas de limite de temps, et chaque réponse est expliquée.",
  "已掌握的题目": "Questions maîtrisées",
  "上一次得分": "Dernier score",
  "示意图": "Schéma",
  "月球在轨道上的位置": "Position de la Lune sur son orbite",
  "太阳光": "Lumière du Soleil",
  "从太空看（北极上方）": "Vu de l'espace (au-dessus du pôle Nord)",
  "从地球看": "Vu de la Terre",
  "农历{0}前后": "Calendrier lunaire : vers le jour {0}",
  "月龄 {0} 天": "Âge de la Lune : {0} jours",
  "被照亮的部分：{0}%": "Partie éclairée : {0} %",
  "月球在地球和太阳之间，暗面朝向地球。": "La Lune est entre la Terre et le Soleil ; sa face sombre est tournée vers la Terre.",
  "月亮正在变圆（盈），亮的一侧在右边。": "La Lune croît ; le côté éclairé est à droite.",
  "地球在月球和太阳之间，整个朝向地球的一面都被照亮。": "La Terre est entre la Lune et le Soleil ; toute la face tournée vers la Terre est éclairée.",
  "月亮正在变缺（亏），亮的一侧在左边。": "La Lune décroît ; le côté éclairé est à gauche.",
  "新月": "Nouvelle Lune",
  "上弦月": "Premier quartier",
  "满月": "Pleine Lune",
  "下弦月": "Dernier quartier",
  "播放一个月": "Lire un mois",
  "月球绕地球一圈约 29.5 天（农历的一个月）。月球自己不发光，总有一半被太阳照亮；我们看到的月相，是这被照亮的一半有多少朝向地球。": "La Lune fait le tour de la Terre en environ 29,5 jours (un mois du calendrier lunaire). La Lune ne produit pas de lumière : la moitié est toujours éclairée par le Soleil. La phase que nous voyons dépend de la part de cette moitié tournée vers la Terre.",
  "约{0}": "vers {0}",
  "八种月相": "Les huit phases",
  "沿轨道的偏离（度）": "Écart le long de l'orbite (degrés)",
  "离开地球轨道面的高度（度）": "Hauteur au-dessus du plan de l'orbite terrestre (degrés)",
  "太阳和月球的位置（从地球看）": "Soleil et Lune (vus de la Terre)",
  "地球的影子和月球的位置": "L'ombre de la Terre et la Lune",
  "本影": "Ombre",
  "半影": "Pénombre",
  "太阳": "Soleil",
  "侧面示意图（高度已放大）": "Vue de côté (hauteur exagérée)",
  "没有日食": "Pas d'éclipse de Soleil",
  "日偏食": "Éclipse partielle de Soleil",
  "日全食或日环食": "Éclipse totale ou annulaire de Soleil",
  "没有月食": "Pas d'éclipse de Lune",
  "半影月食": "Éclipse de Lune par la pénombre",
  "月偏食": "Éclipse partielle de Lune",
  "月全食": "Éclipse totale de Lune",
  "月球与{0}的夹角：{1}°": "Angle entre la Lune et {0} : {1}°",
  "地球的影子中心": "le centre de l'ombre de la Terre",
  "日食只发生在新月（农历初一）；月球的影子很小，只扫过地球上的一条窄带。": "Une éclipse de Soleil n'a lieu qu'à la nouvelle Lune (jour 1 du mois lunaire) ; l'ombre de la Lune est petite et ne balaie qu'une bande étroite de la Terre.",
  "月食只发生在满月（农历十五、十六）；整个夜晚半球的人都能看到。": "Une éclipse de Lune n'a lieu qu'à la pleine Lune (jour 15 ou 16 du mois lunaire) ; tous ceux qui sont du côté nuit peuvent la voir.",
  "日食": "Éclipse de Soleil",
  "月食": "Éclipse de Lune",
  "每个月都有一次新月和一次满月，为什么不是每个月都有日食和月食？因为月球的轨道和地球绕太阳的轨道平面相差约 5°，大多数时候月球从太阳（或地球的影子）的上方或下方经过。": "Il y a une nouvelle Lune et une pleine Lune chaque mois. Pourquoi n'y a-t-il pas une éclipse chaque mois ? L'orbite de la Lune est inclinée d'environ 5° par rapport au plan de l'orbite de la Terre : la plupart du temps, la Lune passe au-dessus ou au-dessous du Soleil (ou de l'ombre de la Terre).",
  "春季": "Printemps",
  "夏季": "Été",
  "秋季": "Automne",
  "冬季": "Hiver",
  "日期（一年中的第几天）": "Date (jour de l'année)",
  "太阳直射点": "Soleil au zénith",
  "北极": "Pôle Nord",
  "地轴倾斜 23.4°，方向不变": "L'axe est incliné de 23,4° et garde sa direction",
  "地球公转（从北极上方看）": "L'orbite de la Terre (vue au-dessus du pôle Nord)",
  "正午太阳高度 {0}°": "Hauteur du Soleil à midi : {0}°",
  "白昼 {0} 小时": "Jour : {0} heures",
  "北半球": "hémisphère nord",
  "太阳直射纬度：{0}°": "Latitude du Soleil au zénith : {0}°",
  "日地距离：{0} 百万千米": "Distance Terre-Soleil : {0} millions de km",
  "北京": "Pékin",
  "悉尼": "Sydney",
  "四季的原因是地轴倾斜，不是离太阳的远近：1 月初地球离太阳最近，北半球却是冬天。": "Les saisons sont dues à l'inclinaison de l'axe de la Terre, pas à la distance au Soleil : début janvier, la Terre est au plus près du Soleil, mais c'est l'hiver dans l'hémisphère nord.",
  "地球一边自转，一边绕太阳公转，地轴始终指向同一个方向（北极星附近）。太阳光直射的位置因此在南北回归线之间来回移动。": "La Terre tourne sur elle-même et autour du Soleil, et son axe pointe toujours dans la même direction (près de l'étoile Polaire). L'endroit où le Soleil est au zénith se déplace donc d'un tropique à l'autre.",
  "高潮": "Marée haute",
  "海水的隆起（已放大）": "Les renflements de la mer (exagérés)",
  "两天内的潮汐（小时）": "Marées sur deux jours (heures)",
  "潮汐强度：{0} ×": "Force de la marée : {0} ×",
  "月相：{0}": "Phase de la Lune : {0}",
  "月球和太阳的引力把海水拉起来，每天约涨落两次，间隔约 12 小时 25 分。新月和满月时太阳、地球、月球在一条直线上，潮最大（大潮，农历初一、十五前后）；上弦和下弦时最小（小潮）。": "L'attraction de la Lune et du Soleil soulève la mer, qui monte et descend environ deux fois par jour, toutes les 12 h 25 min. À la nouvelle et à la pleine Lune, le Soleil, la Terre et la Lune sont alignés et la marée est la plus forte (grande marée, vers les jours 1 et 15 du mois lunaire) ; aux quartiers elle est la plus faible (morte-eau).",
  "海水为什么会涨落？移动月球，看看潮的大小怎样变化。": "Pourquoi la mer monte-t-elle et descend-elle ? Déplacez la Lune et observez comment la marée change.",
  "已过的天数": "Jours écoulés",
  "第 {0} 天": "Jour {0}",
  "公转：{0}° （{1} 圈）": "Révolution : {0}° ({1} tours)",
  "自转：{0} 圈": "Rotation : {0} tours",
  "地球绕太阳转一圈约 365.24 天，这段时间里自转约 366.24 圈，比昼夜的次数多一圈。红点是地面上的一个标记。": "La Terre fait le tour du Soleil en environ 365,24 jours et tourne sur elle-même environ 366,24 fois pendant ce temps, une de plus que le nombre de jours. Le point rouge est un repère au sol.",
  "1 天 / 秒": "1 jour / s",
  "10 天 / 秒": "10 jours / s",
  "30 天 / 秒": "30 jours / s",
  "自转产生昼夜交替，公转产生一年。拖动日期，看地面上的标记转了多少圈。": "La rotation fait le jour et la nuit ; la révolution fait l'année. Faites glisser la date pour voir combien de tours le repère a faits.",
  "月相": "Phases de la Lune",
  "日食和月食": "Éclipses",
  "昼夜与四季": "Jour, nuit et saisons",
  "潮汐": "Marées",
  "自转和公转": "Rotation et révolution",
