  "光走 {0}": "la lumière met {0}",
  "点击行星，进入它的页面。示意距离只保留行星的顺序和方向；真实距离下太阳系几乎是空的。": "Touchez une planète pour ouvrir sa page. Les distances schématiques ne gardent que l'ordre et les directions des planètes ; aux vraies distances, le système solaire est presque vide.",
