  "太空射击": "Tir spatial",
  "拖动飞船自动开火，击落陨石和敌机": "Faites glisser le vaisseau, il tire tout seul. Abattez astéroïdes et vaisseaux ennemis.",
  "拖动手指移动飞船，飞船自动开火。点击炸弹图标或按空格键使用炸弹。": "Faites glisser un doigt pour déplacer le vaisseau, il tire tout seul. Touchez l’icône de bombe ou appuyez sur Espace pour utiliser une bombe.",
